{
  "document_metadata": {
    "title": "Zone Management Act. Section 388 of the Energy Policy Act of 2005",
    "document_number": "[1]",
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Jurisdictional",
      "requirement": "The law grants ultimate authority over offshore wind energy development on the OCS to the Secretary of the Interior; this authority is administered by the Bureau of Ocean Energy Management, an agency within the Department of the Interior.",
      "scope": "Offshore wind energy development on the Outer Continental Shelf (OCS)",
      "source": "Energy Policy Act of 2005, Section 388",
      "related_domains": "Regulatory, Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "States have authority to manage ocean energy resources and structures located in their coastal zones, so long as its regulation does not infringe on the federal government's reserved rights to regulate navigation, commerce, or foreign affairs in state waters.",
      "scope": "Coastal zones of states bordering the Atlantic or Pacific Oceans",
      "source": "Submerged Lands Act of 1953",
      "related_domains": "Regulatory, Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "States bordering the Great Lakes have jurisdiction over submerged lands to the midpoint of each lake; and Texas, Louisiana, and Florida have jurisdiction over the first nine nautical miles of submerged lands in the Gulf of Mexico.",
      "scope": "Great Lakes and Gulf of Mexico",
      "source": "Submerged Lands Act of 1953",
      "related_domains": "Regulatory, Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "BOEM has jurisdiction for leasing and environmental reviews of offshore wind projects on the OCS, while the Army Corps of Engineers will lead federal environmental reviews of projects in the Great Lakes and states will play a larger role in approving those projects.",
      "scope": "Offshore wind projects on the OCS and in the Great Lakes",
      "source": "Submerged Lands Act of 1953",
      "related_domains": "Regulatory, Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "An offshore wind project in federal waters must obtain a 'consistency' determination or certification from the applicable state agency that the proposed activity is consistent to the maximum extent practicable with the enforceable policies of federally-approved but state implemented coastal zone management programs.",
      "scope": "Offshore wind projects in federal waters",
      "source": "Coastal Zone Management Act (CZMA)",
      "related_domains": "Regulatory, Jurisdictional"
    }
  ],
  "regulatory_entities": [
    {
      "entity_name": "Secretary of the Interior",
      "jurisdiction": "Federal",
      "role": "Ultimate authority over offshore wind energy development on the OCS"
    },
    {
      "entity_name": "Bureau of Ocean Energy Management (BOEM)",
      "jurisdiction": "Federal",
      "role": "Administers the authority of the Secretary of the Interior over offshore wind energy development on the OCS"
    },
    {
      "entity_name": "Army Corps of Engineers",
      "jurisdiction": "Federal",
      "role": "Leads federal environmental reviews of offshore wind projects in the Great Lakes"
    },
    {
      "entity_name": "State agencies",
      "jurisdiction": "State",
      "role": "Approve offshore wind projects in the Great Lakes and conduct coastal zone consistency reviews for offshore wind projects in federal waters"
    }
  ]
}

